{"path": "bowling.py", "content": "class BowlingGame:
    def __init__(self):
        self.rolls = []

    def _state(self):
        """Return (frame_index, rolls_in_current_frame) for the rolls so far, frame_index 10 means fill balls."""
        i = 0
        frame = 0
        while frame < 10 and i < len(self.rolls):
            if self.rolls[i] == 10:
                i += 1
            elif i + 1 < len(self.rolls):
                i += 2
            else:
                return frame, self.rolls[i:]
            frame += 1
        return frame, self.rolls[i:]

    def _game_over(self):
        frame, rest = self._state()
        if frame < 10:
            return False
        r = self.rolls
        # find tenth frame start
        i = 0
        for _ in range(9):
            i += 1 if r[i] == 10 else 2
        tenth = r[i:]
        if tenth[0] == 10 or (len(tenth) >= 2 and tenth[0] + tenth[1] == 10):
            return len(tenth) == 3
        return len(tenth) == 2

    def roll(self, pins):
        if pins < 0:
            raise ValueError("negative roll is invalid")
        if pins > 10:
            raise ValueError("pin count exceeds pins on the lane")
        if self._game_over():
            raise IndexError("cannot roll after game is over")
        frame, rest = self._state()
        if frame < 10:
            if rest and rest[0] + pins > 10:
                raise ValueError("pin count exceeds pins on the lane")
        else:
            # fill balls after tenth frame
            r = self.rolls
            i = 0
            for _ in range(9):
                i += 1 if r[i] == 10 else 2
            tenth = r[i:]
            if tenth[0] == 10 and len(tenth) == 2 and tenth[1] != 10 \
                    and tenth[1] + pins > 10:
                raise ValueError("pin count exceeds pins on the lane")
        self.rolls.append(pins)

    def score(self):
        if not self.rolls or not self._game_over():
            raise IndexError("score cannot be taken until the end of the game")
        r = self.rolls
        total = 0
        i = 0
        for _ in range(10):
            if r[i] == 10:
                total += 10 + r[i + 1] + r[i + 2]
                i += 1
            elif r[i] + r[i + 1] == 10:
                total += 10 + r[i + 2]
                i += 2
            else:
                total += r[i] + r[i + 1]
                i += 2
        return total
